def boot(state):
    if state["pending"]:
        if state["tries"] >= 3:
            state["pending"] = None
            return "rollback -> " + state["active"]
        state["tries"] += 1
        return "try " + state["pending_slot"] + " (" + str(state["tries"]) + ")"
    return "boot " + state["active"]

s = {"active": "A", "pending": "v2", "pending_slot": "B", "tries": 0}
for _ in range(4):
    print(boot(s))

