import itertools
f = lambda a, b, c: (a and b) or c
rows = list(itertools.product([0, 1], repeat=3))
pairs = {}
for i, name in enumerate("abc"):
    for r in rows:
        r2 = list(r); r2[i] = 1 - r2[i]; r2 = tuple(r2)
        if f(*r) != f(*r2):
            pairs.setdefault(name, set()).add(tuple(sorted([r, r2])))
best = None
for n in range(1, 9):
    for combo in itertools.combinations(rows, n):
        cs = set(combo)
        if all(any(a in cs and b in cs for a, b in pairs[k]) for k in "abc"):
            best = combo; break
    if best: break
print("min tests", len(best), best)

